from solution import count


def test_issue_example():
    """Example asserts count([True,False,True]) == 2."""
    assert count([True, False, True]) == 2  # 1+0+1 = 2


def test_issue_empty():
    """Count true booleans in empty list is zero."""
    assert count([]) == 0  # 0 Trues so 0 = 0


def test_issue_single_true():
    """Count true booleans in [True] is one."""
    assert count([True]) == 1  # 1 = 1


def test_issue_single_false():
    """Count true booleans in [False] is zero."""
    assert count([False]) == 0  # 0 = 0


def test_issue_all_true():
    """Count true booleans in all-True list."""
    assert count([True, True, True, True]) == 4  # 1+1+1+1 = 4


def test_issue_all_false():
    """Count true booleans in all-False list is zero."""
    assert count([False, False, False]) == 0  # 0+0+0 = 0


def test_issue_mixed_many():
    """Count true booleans in mixed list with Trues and Falses."""
    assert count([True, False, False, True, False, True]) == 3  # 1+0+0+1+0+1 = 3


def test_issue_true_at_end():
    """Count true booleans finds single True at end."""
    assert count([False, False, False, True]) == 1  # 0+0+0+1 = 1


def test_contract_callable():
    """Public interface defines count(lst) in solution."""
    assert callable(count)


def test_contract_returns_int():
    """Example implies count returns an int."""
    assert isinstance(count([True, False]), int)
